CREATE TABLE roles(id TEXT PRIMARY KEY);
CREATE TABLE schools(id TEXT PRIMARY KEY,name TEXT NOT NULL,location TEXT NOT NULL DEFAULT '',code TEXT UNIQUE NOT NULL,admin_contact TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active',created_at REAL NOT NULL);
CREATE TABLE user_schools(user_id TEXT REFERENCES users(id),school_id TEXT REFERENCES schools(id),PRIMARY KEY(user_id,school_id));
CREATE TABLE teachers(user_id TEXT PRIMARY KEY REFERENCES users(id),created_at REAL NOT NULL);
CREATE TABLE classroom_assignments(classroom_id TEXT REFERENCES classrooms(id),user_id TEXT REFERENCES users(id),PRIMARY KEY(classroom_id,user_id));
CREATE TABLE device_sessions(token_hash TEXT PRIMARY KEY,device_id TEXT REFERENCES devices(id),created_at REAL NOT NULL,expires REAL NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE refresh_tokens(token_hash TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),install_id TEXT NOT NULL,device_id TEXT,family_id TEXT NOT NULL,expires REAL NOT NULL,created_at REAL NOT NULL,used_at REAL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE password_reset_tokens(token_hash TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),created_at REAL NOT NULL,expires REAL NOT NULL,used_at REAL);
CREATE TABLE heartbeats(id TEXT PRIMARY KEY,device_id TEXT REFERENCES devices(id),classroom_id TEXT REFERENCES classrooms(id),teacher_id TEXT REFERENCES users(id),at REAL NOT NULL,current_mode TEXT NOT NULL,grade INTEGER NOT NULL,chapter_id TEXT NOT NULL,last_interaction REAL,network_state TEXT NOT NULL,health TEXT NOT NULL,error_count INTEGER NOT NULL,session_count INTEGER NOT NULL,version TEXT NOT NULL);
CREATE INDEX heartbeats_device_time ON heartbeats(device_id,at);
CREATE TABLE activity_events(id TEXT PRIMARY KEY,device_id TEXT REFERENCES devices(id),classroom_id TEXT REFERENCES classrooms(id),teacher_id TEXT REFERENCES users(id),event_type TEXT NOT NULL,session_id TEXT NOT NULL,mode TEXT NOT NULL,grade INTEGER NOT NULL,chapter_id TEXT NOT NULL,occurred_at REAL NOT NULL,received_at REAL NOT NULL,duration_seconds REAL NOT NULL DEFAULT 0,UNIQUE(device_id,session_id,event_type));
CREATE INDEX activity_classroom_time ON activity_events(classroom_id,occurred_at);
CREATE TABLE usage_daily(day TEXT NOT NULL,classroom_id TEXT REFERENCES classrooms(id),mode TEXT NOT NULL,started INTEGER NOT NULL DEFAULT 0,completed INTEGER NOT NULL DEFAULT 0,duration_seconds REAL NOT NULL DEFAULT 0,PRIMARY KEY(day,classroom_id,mode));
CREATE TABLE app_versions(version TEXT PRIMARY KEY,approved INTEGER NOT NULL DEFAULT 0,supported INTEGER NOT NULL DEFAULT 1,created_at REAL NOT NULL,updated_at REAL NOT NULL);
CREATE TABLE error_events(id TEXT PRIMARY KEY,device_id TEXT REFERENCES devices(id),classroom_id TEXT REFERENCES classrooms(id),code TEXT NOT NULL,at REAL NOT NULL);
CREATE INDEX error_events_time ON error_events(at);
CREATE TABLE audit_logs(id TEXT PRIMARY KEY,at REAL NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL DEFAULT '',school_id TEXT);
CREATE TABLE alerts(id TEXT PRIMARY KEY,alert_key TEXT UNIQUE NOT NULL,severity TEXT NOT NULL,school_id TEXT,classroom_id TEXT,device_id TEXT,at REAL NOT NULL,code TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',resolved_at REAL);
CREATE TABLE alert_rules(school_id TEXT PRIMARY KEY,offline_seconds INTEGER NOT NULL DEFAULT 600,error_threshold INTEGER NOT NULL DEFAULT 3,login_threshold INTEGER NOT NULL DEFAULT 5);
CREATE TABLE login_attempts(identity TEXT PRIMARY KEY,started_at REAL NOT NULL,count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE system_state(id INTEGER PRIMARY KEY,revision INTEGER NOT NULL DEFAULT 0);
INSERT INTO system_state(id,revision) VALUES(1,0) ON CONFLICT DO NOTHING;
